/** Diferenças entre duas identidades. Lista vazia = mesma linha. */
function compararIdentidade(antes, agora) {
  return Object.keys(antes).filter((c) => antes[c] !== agora[c]).map((c) => c + ': "' + antes[c] + '" -> "' + agora[c] + '"');
