// ---------------------------------------------------------------------------------------
// Regra da coluna Q (spec 13.5 com a mudança do Claudio de 28/10)
// ---------------------------------------------------------------------------------------
function normalizarQ(v) { return String(v == null ? '' : v).trim().toUpperCase(); }
