  const porAba = {};
  let notasMascarada = null;
  for (const a of abas) {
    const xml = await zip.file(a.parte).async('string');
    porAba[a.nome] = { parte: a.parte, ...secoesDaAba(xml) };
    if (a.nome === abaAlvo) {
      let m = xml;
      for (const ref of refsMascarar || []) m = m.replace(new RegExp('<c\\b[^>]*?\\br="' + ref + '"[^>]*?(?:\\/>|>[\\s\\S]*?<\\/c>)'), '');
