function escRe(s) { return String(s).replace(/[.*+?^$\{}()|[\]\\]/g, '\\$&'); }
// C.3 passo 16(a): o backup do estado atual foi aceito, com nome, pasta e sha1 certos?
const c = $('Escrita N — 01 config e alvos').first().json;
