  r.item('dxfs', ref.styles.dxfs, atual.styles.dxfs, j(ref.styles.dxfs) === j(atual.styles.dxfs));
  r.relato('styles.xml (sha1)', ref.styles.sha1, atual.styles.sha1);
  r.relato('cellXfs', ref.styles.cellXfs, atual.styles.cellXfs);
