async function impressao(zip, abaAlvo, refsMascarar) {
  const partes = {};
  for (const nome of Object.keys(zip.files).sort()) { if (zip.files[nome].dir) continue; partes[nome] = sha1(await zip.file(nome).async('uint8array')); }
