  if (desde < 0) return { ok: false, motivo: 'modified_at no futuro (' + modifiedAt + ')', minutosDesde: desde };
  if (desde < minutos) return { ok: false, motivo: 'modificado há ' + desde.toFixed(1) + ' min (< ' + minutos + ')', minutosDesde: desde };
