  if (tipo === 's') { const v = (dentro.match(/<v>([^<]*)<\/v>/) || [])[1]; valor = v != null && ss[+v] != null ? ss[+v] : ''; }
  else if (tipo === 'inlineStr') valor = textoDosT(dentro);
  else { const v = (dentro.match(/<v>([^<]*)<\/v>/) || [])[1]; valor = v != null ? desescapar(v) : ''; }
