const RE_EXCECOES_PASSO0 = [/^xl\/worksheets\/sheet\d+\.xml$/, /^xl\/styles\.xml$/, /^xl\/sharedStrings\.xml$/, /^xl\/calcChain\.xml$/, /^docProps\//];
